-- Run only in an isolated local schema fixture. All synthetic rows roll back.
BEGIN;
CREATE TEMP TABLE push_checks(name text);
CREATE FUNCTION pg_temp.check_push(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; INSERT INTO push_checks VALUES(label); END $$;
DO $$
DECLARE a uuid:='10000000-0000-4000-8000-000000000001'; b uuid:='10000000-0000-4000-8000-000000000002'; c uuid:='10000000-0000-4000-8000-000000000003';
 sa uuid:='20000000-0000-4000-8000-000000000001'; sb uuid:='20000000-0000-4000-8000-000000000002'; sc uuid:='20000000-0000-4000-8000-000000000003';
 da uuid:='30000000-0000-4000-8000-000000000001'; da2 uuid:='30000000-0000-4000-8000-000000000002'; dc uuid:='30000000-0000-4000-8000-000000000003';
 room1 uuid:=gen_random_uuid(); room2 uuid:=gen_random_uuid(); room3 uuid:=gen_random_uuid(); friendship uuid; n uuid; v jsonb; jobs jsonb; job1 uuid; job2 uuid; rejected boolean;
BEGIN
 PERFORM pg_temp.check_push(NOT has_function_privilege('anon','public.push_settings(text,jsonb)','EXECUTE') AND has_function_privilege('authenticated','public.push_settings(text,jsonb)','EXECUTE') AND NOT has_function_privilege('authenticated','public.push_worker(text,jsonb)','EXECUTE'),'RPC grants separate client and worker');
 PERFORM pg_temp.check_push(NOT has_table_privilege('authenticated','quiz_private.push_devices','SELECT') AND NOT has_table_privilege('anon','quiz_private.push_preferences','SELECT') AND (SELECT count(*)=4 FROM pg_class WHERE relnamespace='quiz_private'::regnamespace AND relname IN('push_config','push_preferences','push_devices','push_outbox') AND relrowsecurity AND relforcerowsecurity),'tokens and preferences have forced RLS and no client table grants');
 INSERT INTO auth.users(id,email,email_confirmed_at,is_anonymous,is_sso_user) VALUES(a,'push-a@example.invalid',now(),false,false),(b,'push-b@example.invalid',now(),false,false),(c,'push-c@example.invalid',now(),false,false);
 INSERT INTO auth.sessions(id,user_id) VALUES(sa,a),(sb,b),(sc,c);
 INSERT INTO quiz_private.player_profiles(id) VALUES(a),(b);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a,'session_id',sa)::text,true);
 v:=public.push_settings('get','{}');
 PERFORM pg_temp.check_push(v->'preferences'->>'enabled'='false' AND v->>'available'='false','safe master default and rollout disabled');
 rejected:=false; BEGIN PERFORM public.push_settings('enable',jsonb_build_object('deviceId',da,'token','ExpoPushToken[synthetic_a]','platform','android')); EXCEPTION WHEN OTHERS THEN rejected:=true; END;
 PERFORM pg_temp.check_push(rejected AND NOT EXISTS(SELECT 1 FROM quiz_private.push_devices),'disabled rollout cannot register tokens');
 UPDATE quiz_private.push_config SET test_actors=ARRAY[a,c] WHERE singleton;
 v:=public.push_settings('enable',jsonb_build_object('deviceId',da,'token','ExpoPushToken[synthetic_a]','platform','android'));
 PERFORM public.push_settings('register',jsonb_build_object('deviceId',da2,'token','ExpoPushToken[synthetic_a2]','platform','ios'));
 PERFORM pg_temp.check_push(v->'preferences'->>'enabled'='true' AND (SELECT count(*)=2 FROM quiz_private.push_devices WHERE user_id=a AND session_id=sa),'two devices bound to the verified actor and session');
 PERFORM public.push_settings('preferences','{"invites":false,"rooms":false,"enabled":false}');
 v:=public.push_settings('enable',jsonb_build_object('deviceId',da,'token','ExpoPushToken[synthetic_a]','platform','android'));
 PERFORM pg_temp.check_push(v->'preferences'->>'invites'='false' AND v->'preferences'->>'rooms'='false','master off on retains subtype preferences');
 rejected:=false;BEGIN PERFORM public.push_settings('preferences','{"enabled":true,"actor":"foreign"}');EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 PERFORM pg_temp.check_push(rejected,'client supplied actor and permission bypass rejected');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',b,'session_id',sb)::text,true);
 PERFORM public.push_settings('revoke',jsonb_build_object('deviceId',da));
 rejected:=false;BEGIN PERFORM public.push_settings('register',jsonb_build_object('deviceId',da,'token','ExpoPushToken[synthetic_a]','platform','android'));EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 PERFORM pg_temp.check_push(rejected AND (SELECT count(*)=2 FROM quiz_private.push_devices WHERE user_id=a),'another account cannot revoke or take over a device');
 INSERT INTO quiz_private.friendships(sender,recipient) VALUES(b,a) RETURNING id INTO friendship;
 SELECT id INTO n FROM public.player_notifications WHERE recipient_id=a AND reference_id=friendship;
 PERFORM quiz_private.notify_player(a,'friend_request',friendship);
 PERFORM pg_temp.check_push((SELECT count(*)=2 FROM quiz_private.push_outbox WHERE user_id=a),'existing real friendship event queues once per device despite duplicate envelopes');
 PERFORM pg_temp.check_push(public.push_settings('target',jsonb_build_object('notificationId',n)) IS NULL,'cross user notification deep link denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a,'session_id',sa)::text,true);
 v:=public.push_settings('target',jsonb_build_object('notificationId',n));
 PERFORM pg_temp.check_push(v->>'kind'='notification' AND v->>'id'=n::text,'own deep link resolves only a server authorized internal target');
 PERFORM public.push_settings('preferences','{"friends":false}');
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 jobs:=public.push_worker('claim','{}');
 PERFORM pg_temp.check_push(jsonb_array_length(jobs)=0 AND (SELECT count(*)=2 FROM quiz_private.push_outbox WHERE state='suppressed'),'preferences rechecked after queueing and before sending');
 -- A fresh event after re-enabling. Old suppressed events never revive.
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a,'session_id',sa)::text,true);
 PERFORM public.push_settings('preferences','{"friends":true}');
 UPDATE quiz_private.friendships SET state='accepted' WHERE id=friendship;
 -- Actual accepted event goes to b (off); use a new own accepted envelope.
 PERFORM quiz_private.notify_player(a,'friend_accepted',friendship);
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 jobs:=public.push_worker('claim','{}');
 job1:=(jobs->0->>'id')::uuid; job2:=(jobs->1->>'id')::uuid;
 PERFORM pg_temp.check_push(jsonb_array_length(jobs)=2 AND jsonb_array_length(public.push_worker('claim','{}'))=0,'worker claiming is replay safe with no second send claim');
 PERFORM public.push_worker('finish',jsonb_build_object('id',job1,'ticket','synthetic_ticket'));
 -- Rotate the same device after a ticket: its stale receipt cannot disable the new token.
 SELECT device_id INTO da FROM quiz_private.push_outbox WHERE id=job1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a,'session_id',sa)::text,true);
 PERFORM public.push_settings('register',jsonb_build_object('deviceId',da,'token','ExpoPushToken[synthetic_rotated]','platform','android'));
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 PERFORM public.push_worker('receipt',jsonb_build_object('id',job1,'status','error','error','DeviceNotRegistered'));
 PERFORM public.push_worker('finish',jsonb_build_object('id',job2,'error','DeviceNotRegistered'));
 PERFORM pg_temp.check_push((SELECT active FROM quiz_private.push_devices WHERE id=da) AND (SELECT count(*)=1 FROM quiz_private.push_devices WHERE user_id=a AND NOT active),'invalid tokens disabled but stale receipt cannot disable rotated token');
 v:=public.push_worker('finish',jsonb_build_object('id',job2,'ticket','synthetic_duplicate'));
 PERFORM pg_temp.check_push(v->>'saved'='false','completed send bookkeeping cannot be overwritten');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a,'session_id',sa)::text,true);
 INSERT INTO quiz_private.live_rooms(id,code,host_id,request_id,dataset) VALUES(room1,'PUSHAZ',b,gen_random_uuid(),'local-push-fixture');
 INSERT INTO quiz_private.live_members(room_id,player_id) VALUES(room1,a),(room1,b);
 UPDATE quiz_private.live_rooms SET state='countdown',start_at=now()-interval '1 second' WHERE id=room1;
 PERFORM pg_temp.check_push(NOT EXISTS(SELECT 1 FROM quiz_private.push_outbox WHERE reference_id=room1),'room preference off prevents real start event delivery');
 PERFORM public.push_settings('preferences','{"rooms":true}');
 INSERT INTO quiz_private.live_rooms(id,code,host_id,request_id,dataset) VALUES(room2,'PUSHBZ',b,gen_random_uuid(),'local-push-fixture');
 INSERT INTO quiz_private.live_members(room_id,player_id) VALUES(room2,a),(room2,b);
 UPDATE quiz_private.live_rooms SET state='countdown',start_at=now()-interval '1 second' WHERE id=room2;
 v:=public.push_settings('target',jsonb_build_object('notificationId',room2,'source','room'));
 PERFORM pg_temp.check_push(v->>'kind'='room' AND v->>'id'=room2::text AND NOT EXISTS(SELECT 1 FROM public.player_notifications WHERE reference_id=room2),'room uses existing authoritative state without breaking older inbox kinds');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',c,'session_id',sc)::text,true);
 PERFORM pg_temp.check_push(public.push_settings('target',jsonb_build_object('notificationId',room2,'source','room')) IS NULL,'non member cannot resolve room push');
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 jobs:=public.push_worker('claim','{}');
 PERFORM pg_temp.check_push(jsonb_array_length(jobs)=1 AND jobs->0->>'source'='room' AND public.push_worker('authorize',jsonb_build_object('id',jobs->0->>'id'))='true'::jsonb,'real room event claims a single valid internal push target');
 -- Exhaust one device's rate budget; those rows must not block later recipients.
 INSERT INTO quiz_private.push_outbox(user_id,device_id,kind,reference_id,state,submitted_at)
 SELECT a,da,'room_started',gen_random_uuid(),'failed',now() FROM generate_series(1,6);
 INSERT INTO quiz_private.live_rooms(id,code,host_id,request_id,dataset) VALUES(room3,'PUSHCZ',b,gen_random_uuid(),'local-push-fixture');
 INSERT INTO quiz_private.live_members(room_id,player_id) VALUES(room3,a),(room3,b);
 UPDATE quiz_private.live_rooms SET state='countdown',start_at=now()-interval '1 second' WHERE id=room3;
 jobs:=public.push_worker('claim','{}');
 PERFORM pg_temp.check_push(jsonb_array_length(jobs)=0 AND EXISTS(SELECT 1 FROM quiz_private.push_outbox WHERE reference_id=room3 AND state='suppressed' AND error_code='RateLimited') AND NOT EXISTS(SELECT 1 FROM quiz_private.push_outbox WHERE state='queued'),'rate limited events are suppressed rather than starving the shared queue');
 DELETE FROM auth.sessions WHERE id=sa;
 PERFORM public.push_worker('claim','{}');
 PERFORM pg_temp.check_push(NOT EXISTS(SELECT 1 FROM quiz_private.push_devices WHERE user_id=a),'revoked session suppresses and cleans its devices');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a,'session_id',sa)::text,true);
 rejected:=false;BEGIN PERFORM public.push_settings('get','{}');EXCEPTION WHEN insufficient_privilege THEN rejected:=true;END;
 PERFORM pg_temp.check_push(rejected,'expired or revoked session cannot register');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',c,'session_id',sc)::text,true);
 PERFORM public.push_settings('enable',jsonb_build_object('deviceId',dc,'token','ExpoPushToken[synthetic_erasure]','platform','android'));
 DELETE FROM auth.users WHERE id=c;
 PERFORM pg_temp.check_push(NOT EXISTS(SELECT 1 FROM quiz_private.push_preferences WHERE user_id=c) AND NOT EXISTS(SELECT 1 FROM quiz_private.push_devices WHERE user_id=c) AND EXISTS(SELECT 1 FROM auth.users WHERE id=b),'Auth deletion cascades push data and preserves other account');
END $$;
SELECT count(*) AS passed_push_sql_checks FROM push_checks;
ROLLBACK;
